workedExamples.code:
#include <iostream>
bool valid(int price, int qty) {
    return price >= 0 && price <= 1000 && qty >= 0 && qty <= 1000;
}
int subtotal(int price, int qty) {
    return price * qty;
}
int main() {
    int price, qty;
    if (!(std::cin >> price >> qty)) { std::cout << "invalid\n"; return 0; }
    if (!valid(price, qty)) { std::cout << "invalid\n"; return 0; }
    std::cout << subtotal(price, qty) << '\n';
}

#include <iostream>
bool valid(int price, int qty, int discount) {
    return price >= 0 && price <= 1000 && qty >= 0 && qty <= 1000 && discount >= 0 && discount <= 100;
}
int subtotal(int price, int qty) {
    return price * qty;
}
int discountPrice(int amount, int percent) {
    return amount - amount * percent / 100;
}
int main() {
    int price, qty, discount;
    if (!(std::cin >> price >> qty >> discount)) { std::cout << "invalid\n"; return 0; }
    if (!valid(price, qty, discount)) { std::cout << "invalid\n"; return 0; }
    std::cout << discountPrice(subtotal(price, qty), discount) << '\n';
}

